i2c-mpu-adafruit.source:
// The usual student sketch: Adafruit_MPU6050.
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>
#include <Wire.h>

Adafruit_MPU6050 mpu;

void setup() {
  Serial.begin(115200);
  if (!mpu.begin()) { Serial.println("no mpu"); while (1) delay(10); }
  Serial.println("mpu ok");
}

void loop() {
  sensors_event_t a, g, t;
  mpu.getEvent(&a, &g, &t);
  Serial.print("z:"); Serial.print(a.acceleration.z, 1);
  Serial.print(" x:"); Serial.print(a.acceleration.x, 1);
  Serial.print(" t:"); Serial.println(t.temperature, 0);
  delay(100);
}

i2c-mpu-raw.source:
// Raw Wire access to an MPU-6050 at 0x68: is it there, who is it, then accel X/Y/Z every 100 ms.
#include <Wire.h>

void setup() {
  Serial.begin(115200);
  Wire.begin();
  Wire.beginTransmission(0x68);
  Serial.print("ack:"); Serial.println(Wire.endTransmission());
  Wire.beginTransmission(0x68); Wire.write(0x75); Wire.endTransmission(false);
  Wire.requestFrom(0x68, 1);
  Serial.print("who:"); Serial.println(Wire.read(), HEX);
  Wire.beginTransmission(0x68); Wire.write(0x6B); Wire.write(0); Wire.endTransmission();   // wake up
}

void loop() {
  Wire.beginTransmission(0x68); Wire.write(0x3B); Wire.endTransmission(false);
  Wire.requestFrom(0x68, 6);
  int16_t ax = Wire.read() << 8; ax |= Wire.read();
  int16_t ay = Wire.read() << 8; ay |= Wire.read();
  int16_t az = Wire.read() << 8; az |= Wire.read();
  Serial.print("a:"); Serial.print(ax); Serial.print(','); Serial.print(ay); Serial.print(','); Serial.println(az);
  delay(100);
}

i2c-oled.source:
// Adafruit_SSD1306 at 0x3C: a 10×10 block in the top-left corner and one pixel in the bottom-right.
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);

void setup() {
  Serial.begin(115200);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { Serial.println("no oled"); while (1); }
  display.clearDisplay();
  display.fillRect(0, 0, 10, 10, SSD1306_WHITE);
  display.drawPixel(127, 63, SSD1306_WHITE);
  display.display();
  Serial.println("drawn");
}

void loop() {}

millis-blink.source:
// Non-blocking blink driven by millis() — needs Timer0 overflow interrupts working.
unsigned long last = 0;
bool on = false;
void setup() { pinMode(LED_BUILTIN, OUTPUT); }
void loop() {
  if (millis() - last >= 250) {
    last += 250;
    on = !on;
    digitalWrite(LED_BUILTIN, on);
  }
}

