real-cpp.source:
// Language features the old mini-compiler could not build: float, long, String, math, struct, class.
struct Point { int x; int y; };
class Counter {
  public:
    Counter() : n(0) {}
    long next() { n += 100000L; return n; }
  private:
    long n;
};
void setup() {
  Serial.begin(9600);
  float r = sqrt(2.0);
  Serial.println(r, 4);
  Counter c;
  c.next(); c.next();
  Serial.println(c.next());
  Point p = {3, 4};
  Serial.println(p.x * p.x + p.y * p.y);
  String s = "abc";
  s += String(42);
  s.toUpperCase();
  Serial.println(s);
  Serial.println(millis() < 1000UL ? "early" : "late");
}
void loop() {}

seg-count.source:
const byte seg[10] = {0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F};
void setup() { for (int p = 2; p <= 9; p++) pinMode(p, OUTPUT); }
void loop() {
  for (int n = 0; n < 10; n++) {
    for (int i = 0; i < 8; i++) digitalWrite(2 + i, (seg[n] >> i) & 1);
    delay(400);
  }
}

seg-rgb.source:
// Digit "3" on a 7-segment display (D2..D9 = A B C D E F G DP) and magenta on an RGB LED (A0 red, A1 green, A2 blue).
void setup() {
  for (int p = 2; p <= 9; p++) pinMode(p, OUTPUT);
  pinMode(A0, OUTPUT); pinMode(A1, OUTPUT); pinMode(A2, OUTPUT);
  digitalWrite(2, HIGH); digitalWrite(3, HIGH); digitalWrite(4, HIGH); digitalWrite(5, HIGH); digitalWrite(8, HIGH);
  digitalWrite(A0, HIGH); digitalWrite(A2, HIGH);
}
void loop() {}

serial-echo.source:
// Serial TX + RX: greets, then echoes what it receives in upper case.
void setup() {
  Serial.begin(9600);
  Serial.println("Hello from Arduino");
}
void loop() {
  while (Serial.available() > 0) {
    char c = Serial.read();
    if (c >= 'a' && c <= 'z') c = c - 32;
    Serial.write(c);
  }
}
